SELECT ROUND(AVG((cpu_usage_percent + gpu_usage_percent) / 2), 2) AS computeUsageRate, ROUND(AVG(memory_usage_percent), 2) AS storageUsageRate, ROUND(AVG(bandwidth_out_percent), 2) AS outputTransportUsageRate, ROUND(AVG(bandwidth_in_percent), 2) AS inputTransportUsageRate FROM node_metrics_history WHERE ip IN
#{ip}
AND (ip, created_at) IN ( SELECT ip, MAX(created_at) FROM node_metrics_history WHERE ip IN
#{ip}
GROUP BY ip )

SELECT ROUND(AVG((cpu_usage_percent + gpu_usage_percent) / 2), 2) AS computeUsageRate, ROUND(AVG(memory_usage_percent), 2) AS storageUsageRate, ROUND(AVG(bandwidth_out_percent), 2) AS outputTransportUsageRate, ROUND(AVG(bandwidth_in_percent), 2) AS inputTransportUsageRate, -- 👇 时间格式化 DATE_FORMAT( DATE_ADD( DATE_SUB(created_at, INTERVAL SECOND(created_at) % 30 SECOND), INTERVAL 30 SECOND ), '%H:%i:%s' ) AS createdAt FROM node_metrics_history WHERE ip IN
#{ip}
AND created_at >= DATE_SUB(NOW(), INTERVAL #{minutes} MINUTE) GROUP BY DATE_FORMAT( DATE_ADD( DATE_SUB(created_at, INTERVAL SECOND(created_at) % 30 SECOND), INTERVAL 30 SECOND ), '%H:%i:%s' ) ORDER BY createdAt ASC

SELECT ROUND(AVG((cpu_usage_percent + gpu_usage_percent) / 2), 2) AS computeUsageRate, ROUND(AVG(memory_usage_percent), 2) AS storageUsageRate, ROUND(AVG(bandwidth_out_percent), 2) AS outputTransportUsageRate, ROUND(AVG(bandwidth_in_percent), 2) AS inputTransportUsageRate FROM node_metrics_history WHERE node_id IN
#{deviceId}
AND (node_id, created_at) IN ( SELECT node_id, MAX(created_at) FROM node_metrics_history WHERE node_id IN
#{deviceId}
GROUP BY node_id )

SELECT ROUND(AVG((cpu_usage_percent + gpu_usage_percent) / 2), 2) AS computeUsageRate, ROUND(AVG(memory_usage_percent), 2) AS storageUsageRate, ROUND(AVG(bandwidth_out_percent), 2) AS outputTransportUsageRate, ROUND(AVG(bandwidth_in_percent), 2) AS inputTransportUsageRate, DATE_FORMAT( DATE_ADD( DATE_SUB(created_at, INTERVAL SECOND(created_at) % ${bucketSeconds} SECOND), INTERVAL ${bucketSeconds} SECOND ), '%Y-%m-%d %H:%i:%s' ) AS createdAt FROM node_metrics_history WHERE node_id IN
#{deviceId}
AND created_at >= ( SELECT DATE_SUB(COALESCE(MAX(created_at), NOW()), INTERVAL #{minutes} MINUTE) FROM node_metrics_history WHERE node_id IN
#{deviceId}
) GROUP BY DATE_FORMAT( DATE_ADD( DATE_SUB(created_at, INTERVAL SECOND(created_at) % ${bucketSeconds} SECOND), INTERVAL ${bucketSeconds} SECOND ), '%Y-%m-%d %H:%i:%s' ) ORDER BY createdAt ASC

SELECT id, node_id as nodeId, cpu_usage_core as cpuUsageCore, cpu_usage_percent as cpuUsagePercent, memory_usage_percent as memoryUsagePercent, memory_used_bytes as memoryUsedBytes, memory_freq_current_mhz as memoryFreqCurrentMhz, gpu_usage_percent as gpuUsagePercent, gpu_mem_used_bytes as gpuMemUsedBytes, bandwidth_in_bps as bandwidthInBps, bandwidth_out_bps as bandwidthOutBps, bandwidth_in_percent as bandwidthInPercent, bandwidth_out_percent as bandwidthOutPercent, net_rtt_avg_ms as netRttAvgMs, net_packet_loss_percent as netPacketLossPercent, created_at as createdAt FROM node_metrics_history WHERE (node_id, created_at) IN ( SELECT node_id, MAX(created_at) FROM node_metrics_history WHERE node_id IN
#{deviceId}
GROUP BY node_id )
